import{_ as e,o as a,c as r,aw as l}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"URL и URI","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/theory/url.md","filePath":"wiki/dev-commit/network/network/theory/url.md"}'),o={name:"wiki/dev-commit/network/network/theory/url.md"};function s(i,t,n,p,c,d){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="url-и-uri" tabindex="-1">URL и URI <a class="header-anchor" href="#url-и-uri" aria-label="Permalink to &quot;URL и URI&quot;">​</a></h1><h2 id="определения" tabindex="-1">Определения <a class="header-anchor" href="#определения" aria-label="Permalink to &quot;Определения&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>URI</strong> (Uniform Resource Identifier) - унифицированный идентификатор ресурса</li><li>Имя и адрес ресурса в сети, включает в себя URL и URN</li><li><a href="https://wiki.ru/img/logo.png" target="_blank" rel="noreferrer">https://wiki.ru/img/logo.png</a></li></ul></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>URL</strong> (Uniform Resource Locator) - унифицированный определитель местонахождения ресурса</li><li>Адрес ресурса в сети, определяет местонахождение и способ обращения к нему</li><li><a href="https://wiki.ru" target="_blank" rel="noreferrer">https://wiki.ru</a></li></ul></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>URN</strong> (Unifrorm Resource Name) - унифицированное имя ресурса</li><li>Имя ресурса в сети, определяет только название ресурса, но не говорит как к нему подключиться</li><li>img/logo.png</li></ul></div><h2 id="структура-uri" tabindex="-1">Структура URI <a class="header-anchor" href="#структура-uri" aria-label="Permalink to &quot;Структура URI&quot;">​</a></h2><ul><li><strong>Scheme</strong> (Схема) - показывает на то, как обращаться к ресурсу, чаще всего это сетевой протокол (http, ftp, ldap)</li><li><strong>Hier-Part</strong> (Иерархическая часть) - данные, необходимые для идентификации ресурса (н-р, адрес сайта)</li><li><strong>Query</strong> (Запрос) - необязательные дополнительные данные ресурса (н-р, поисковой запрос)</li><li><strong>Fragment</strong> (Фрагмент) - необязательный компонент для идентификации вторичного ресурса ресурса (н-р, место на странице)</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">URI</span><span style="color:#50A14F;"> =</span><span style="color:#50A14F;"> scheme</span><span style="color:#50A14F;"> &quot;:&quot;</span><span style="color:#50A14F;"> hier-part</span><span style="color:#383A42;"> [ </span><span style="color:#50A14F;">&quot;?&quot;</span><span style="color:#50A14F;"> query</span><span style="color:#50A14F;"> ]</span><span style="color:#383A42;"> [ </span><span style="color:#50A14F;">&quot;#&quot;</span><span style="color:#50A14F;"> fragment</span><span style="color:#50A14F;"> ]</span></span></code></pre></div><h2 id="структура-url" tabindex="-1">Структура URL <a class="header-anchor" href="#структура-url" aria-label="Permalink to &quot;Структура URL&quot;">​</a></h2><ul><li>Протокол, который используется для доступа к ресурсу – http, https, ftp</li><li>Расположение сервера с использованием IP-адреса или имени домена - например, wiki.merionet.ru - это имя домена. <a href="https://192.168.1.17" target="_blank" rel="noreferrer">https://192.168.1.17</a> - здесь ресурс расположен по указанному IP-адресу</li><li>Номер порта на сервере. Н-р, <a href="http://localhost" target="_blank" rel="noreferrer">http://localhost</a>: 8080, где 8080 - это порт</li><li>Точное местоположение в структуре каталогов сервера. Н-р - <a href="https://wiki.merionet.ru/ip-telephoniya/" target="_blank" rel="noreferrer">https://wiki.merionet.ru/ip-telephoniya/</a> - это точное местоположение, если пользователь хочет перейти в раздел про телефонию на сайте</li><li>Необязательный идентификатор фрагмента. Н-р, <a href="https://www.google.com/search?ei=qw3eqwe12e1w&amp;q=URL" target="_blank" rel="noreferrer">https://www.google.com/search?ei=qw3eqwe12e1w&amp;q=URL</a>, где q = URL - это строка запроса, введенная пользователем</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">[protocol]://www.[domain_name]:[port 80]/[path or exaction resource location]?[query]#[fragment]</span></span></code></pre></div><h3 id="пример" tabindex="-1">Пример <a class="header-anchor" href="#пример" aria-label="Permalink to &quot;Пример&quot;">​</a></h3><div class="language-plaintext"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span>https://www.example.com:80/file.html?key1=value1&amp;key2=value2#00s0350q</span></span></code></pre></div><table tabindex="0"><thead><tr><th>https://</th><th>Protocol</th></tr></thead><tbody><tr><td>www.</td><td>Sub Domain</td></tr><tr><td>example.com</td><td>Domain Name</td></tr><tr><td>:80</td><td>Port</td></tr><tr><td>/file.html</td><td>Path</td></tr><tr><td>?</td><td>Query</td></tr><tr><td>key1=value1&amp;key2=value2</td><td>Parameters</td></tr><tr><td>#00s0350q</td><td>Fragment</td></tr></tbody></table>',14)])])}const m=e(o,[["render",s]]);export{u as __pageData,m as default};
